insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_professional','professional','adjective','showing the skill and high standards expected of someone who is trained for a job','[{"senseId":"professional_1","meaning":"showing the skill and high standards expected of someone who is trained for a job","acceptedParaphrases":["skilled","expert"],"masteryContexts":[{"contextId":"u2_31_professional_meaning","text":"He gave a professional performance, even though he was nervous.","meaning":"showing the skill and high standards expected","wrongMeanings":["showing great fear and a lack of practice","showing an unusual wish to be paid","showing the kindness and humour expected"]},{"contextId":"u2_31_professional_paraphrase","text":"You should get professional advice before making a big decision.","meaning":"from a trained expert","wrongMeanings":["from a company’s advertisements","from an anonymous stranger","from a recent newspaper"]}],"situationDistractors":["The beginner nervously played his first song at the school concert.","A volunteer painted the fence on Saturday morning just for fun.","The mechanic forgot his tools and arrived two hours late.","The village team plays on Sunday mornings, and nobody receives any money for it.","The neighbour mended the fence badly because he had never done it before.","The tourist took a few photographs on her phone and shared them with her friends."],"gapDistractors":[{"contextId":"u2_31_professional_gap_1","answer":"professional","wrong":["amateur","casual","inexperienced"]},{"contextId":"u2_31_professional_gap_2","answer":"professional","wrong":["beginner","amateur","inexperienced"]},{"contextId":"u2_31_professional_gap_3","answer":"professional","wrong":["casual","careless","nervous"]}],"spellingErrors":["profesional","professinal","proffessional","proffesional","professionel","profesionnal"],"wordFamilyForms":[{"form":"professional","partOfSpeech":"adjective","example":"She gave a very professional presentation to the company directors.","pedagogicallyUseful":true},{"form":"profession","partOfSpeech":"noun","example":"Teaching is a respected profession in many countries.","pedagogicallyUseful":true},{"form":"professionally","partOfSpeech":"adverb","example":"The photographs were taken professionally, so they look like magazine pictures.","pedagogicallyUseful":true},{"form":"unprofessional","partOfSpeech":"adjective","example":"It was unprofessional of the guide to arrive an hour late.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_31_professional_passage_1","contextId":"u2_31_professional_gap_1","text":"Amateur players train after work and are not paid. In contrast, a ____ footballer plays full time and earns a salary from a club.","answer":"professional"},{"passageId":"u2_31_professional_passage_2","contextId":"u2_31_professional_gap_2","text":"The wiring in the old house was dangerous, so we did not try to repair it ourselves. We hired a ____ electrician who had years of training.","answer":"professional"}],"contextDependentParaphrases":[],"wrongParaphrases":["careless","nervous","famous"],"misleadingDistractors":["badly prepared and careless","done only for fun","free of charge"]}]'::jsonb,'["profession","professionally","unprofessional"]'::jsonb,'["professional footballer","professional advice","professional photographer"]'::jsonb,'live'),
('vocab_regional','regional','adjective','relating to a particular area of a country or of the world','[{"senseId":"regional_1","meaning":"relating to a particular area of a country or of the world","acceptedParaphrases":["local","of one area"],"masteryContexts":[{"contextId":"u2_32_regional_meaning","text":"Many British accents are regional, so people can often guess where a speaker grew up.","meaning":"belonging to a particular part of a country","wrongMeanings":["belonging to a country’s capital city","belonging to people of one age group","belonging to a different country"]},{"contextId":"u2_32_regional_paraphrase","text":"The regional manager visits each shop in the south-west.","meaning":"responsible for one area","wrongMeanings":["responsible for one shop","responsible for one department","responsible for one project"]}],"situationDistractors":["The international airline flew passengers between twenty countries.","The national government announced a rule for the entire country.","A world-famous chef opened restaurants on every continent.","The prime minister gave a speech about plans for the whole country.","The neighbours organised a small party in their street for the summer.","The embassy in Paris published an announcement about visas for people from every country."],"gapDistractors":[{"contextId":"u2_32_regional_gap_1","answer":"regional","wrong":["national","international","global"]},{"contextId":"u2_32_regional_gap_2","answer":"regional","wrong":["international","global","worldwide"]},{"contextId":"u2_32_regional_gap_3","answer":"regional","wrong":["national","global","international"]}],"spellingErrors":["regonal","reigional","regeonal","regionel","regionall","reagional"],"masteryPassages":[{"passageId":"u2_32_regional_passage_1","contextId":"u2_32_regional_gap_1","text":"The national news covers the whole country, but our ____ newspaper reports mainly on events in Yorkshire. It tells readers about local sports teams and council decisions.","answer":"regional"},{"passageId":"u2_32_regional_passage_2","contextId":"u2_32_regional_gap_2","text":"The company divided Britain into five areas. Each ____ manager is responsible for the shops in one of them, such as Scotland or the south-west.","answer":"regional"}],"contextDependentParaphrases":[],"wrongParaphrases":["national","global","historic"],"misleadingDistractors":["worldwide and international","very old and traditional","prepared at home"]}]'::jsonb,'[]'::jsonb,'["regional accent","regional manager","regional newspaper"]'::jsonb,'live'),
('vocab_commentary','commentary','noun','a spoken description of an event as it happens','[{"senseId":"commentary_1","meaning":"a spoken description of an event as it happens","acceptedParaphrases":["live description","spoken report"],"masteryContexts":[{"contextId":"u2_33_commentary_meaning","text":"The radio commentary of the race was full of excitement.","meaning":"a spoken description of an event as it happens","wrongMeanings":["a written report of an event after it ends","a list of results printed after an event","a photograph of an event shown on screen"]},{"contextId":"u2_33_commentary_paraphrase","text":"The football commentary was so lively that listeners felt they were at the stadium.","meaning":"a live spoken description of a match","wrongMeanings":["a recorded written summary of a season","a printed table of scores in a match","a loud song sung by fans at a match"]}],"situationDistractors":["The printed programme listed all the players and their numbers.","The scoreboard showed the final result of the match.","The referee blew the whistle and stopped play.","The newspaper printed a long report about the match the next morning.","The coach gave a short interview to a journalist after the game.","The fans sang loudly and waved flags throughout the second half."],"gapDistractors":[{"contextId":"u2_33_commentary_gap_1","answer":"commentary","wrong":["scoreboard","schedule","advertisement"]},{"contextId":"u2_33_commentary_gap_2","answer":"commentary","wrong":["timetable","receipt","menu"]},{"contextId":"u2_33_commentary_gap_3","answer":"commentary","wrong":["scoreboard","weather","traffic"]}],"spellingErrors":["comentary","commentry","commentery","commenatry","comentry","commentarry"],"wordFamilyForms":[{"form":"commentary","partOfSpeech":"noun","example":"The radio commentary made the race sound even more exciting.","pedagogicallyUseful":true},{"form":"comment","partOfSpeech":"verb","example":"The headteacher refused to comment on the rumours.","pedagogicallyUseful":true,"altExample":"Several players refused to comment after the match."},{"form":"commentator","partOfSpeech":"noun","example":"The commentator described every pass of the match.","pedagogicallyUseful":true,"altExample":"The commentator became hoarse after shouting for ninety minutes."}],"masteryPassages":[{"passageId":"u2_33_commentary_passage_1","contextId":"u2_33_commentary_gap_1","text":"Many fans cannot get tickets, so they listen to the match on the radio. The ____ describes every pass and shot as it happens.","answer":"commentary"},{"passageId":"u2_33_commentary_passage_2","contextId":"u2_33_commentary_gap_2","text":"The final of the tournament was close, but the television ____ made it even more exciting. The speakers’ voices rose with every goal.","answer":"commentary"}],"contextDependentParaphrases":[],"wrongParaphrases":["written summary","final score","long interview"],"misleadingDistractors":["a list of match results","an advertisement during a break","a written summary of the rules"]}]'::jsonb,'["comment","commentator"]'::jsonb,'["live commentary","radio commentary","football commentary"]'::jsonb,'live'),
('vocab_educational','educational','adjective','giving knowledge or teaching useful things','[{"senseId":"educational_1","meaning":"giving knowledge or teaching useful things","acceptedParaphrases":["teaching","instructive"],"masteryContexts":[{"contextId":"u2_34_educational_meaning","text":"The documentary was both entertaining and educational.","meaning":"teaching useful things","wrongMeanings":["showing very old photographs","making people laugh loudly","costing a great deal to make"]},{"contextId":"u2_34_educational_paraphrase","text":"Good apps for young children are educational, helping them learn letters and numbers.","meaning":"designed to help people learn","wrongMeanings":["designed to keep people busy","designed to make people spend money","designed to help people sleep"]}],"situationDistractors":["The family played a board game purely for amusement on Sunday evening.","The comedian told jokes for two hours at the theatre.","The shop sold toys that had no instructions or learning purpose.","The cartoon was colourful, silly and full of noisy music.","The shop sells toys, sweets and birthday cards for children.","The students played a fast game on their phones during the break."],"gapDistractors":[{"contextId":"u2_34_educational_gap_1","answer":"educational","wrong":["pointless","harmful","useless"]},{"contextId":"u2_34_educational_gap_2","answer":"educational","wrong":["pointless","misleading","unrelated"]},{"contextId":"u2_34_educational_gap_3","answer":"educational","wrong":["pointless","misleading","boring"]}],"spellingErrors":["educasional","eductional","educatinal","educationel","educatonal","edducational"],"wordFamilyForms":[{"form":"educational","partOfSpeech":"adjective","example":"The museum offers educational visits for primary schools.","pedagogicallyUseful":true},{"form":"educate","partOfSpeech":"verb","example":"Schools must educate children about online safety.","pedagogicallyUseful":true,"altExample":"The campaign aims to educate people about the dangers of fake news."},{"form":"education","partOfSpeech":"noun","example":"Free education gives every child the chance to succeed.","pedagogicallyUseful":true,"altExample":"Good education depends on well-trained teachers."}],"masteryPassages":[{"passageId":"u2_34_educational_passage_1","contextId":"u2_34_educational_gap_1","text":"The school did not want children to waste their time online. It chose games and websites that were ____, because they taught maths and science.","answer":"educational"},{"passageId":"u2_34_educational_passage_2","contextId":"u2_34_educational_gap_2","text":"The museum trip was fun, but it was also ____. By the end of the day, the students had learnt a great deal about the history of the town.","answer":"educational"}],"contextDependentParaphrases":[],"wrongParaphrases":["relaxing","expensive","frightening"],"misleadingDistractors":["only for entertainment","extremely expensive","related to money"]}]'::jsonb,'["educate","education"]'::jsonb,'["educational game","educational visit","educational programme"]'::jsonb,'live'),
('vocab_culture','culture','noun','the customs, beliefs and way of life of a particular group of people','[{"senseId":"culture_1","meaning":"the customs, beliefs and way of life of a particular group of people","acceptedParaphrases":["way of life","customs and traditions"],"masteryContexts":[{"contextId":"u2_35_culture_meaning","text":"Food is an important part of Italian culture.","meaning":"customs, beliefs and way of life","wrongMeanings":["buildings, roads and bridges","laws, taxes and punishments","jobs, wages and prices"]},{"contextId":"u2_35_culture_paraphrase","text":"Music and food are important parts of local culture.","meaning":"the customs and way of life of a group","wrongMeanings":["the history and age of a town","the size and wealth of a city","the climate and land of a region"]}],"situationDistractors":["The tourist took photographs of the mountains and the lake.","The government changed the tax rules for small businesses.","The traveller exchanged his money at the airport.","The tourists took photographs of the old castle and the harbour.","The weather in the north is usually cold and wet in winter.","The new road to the airport was finished two months earlier than planned."],"gapDistractors":[{"contextId":"u2_35_culture_gap_1","answer":"culture","wrong":["climate","weather","landscape"]},{"contextId":"u2_35_culture_gap_2","answer":"culture","wrong":["climate","landscape","population"]},{"contextId":"u2_35_culture_gap_3","answer":"culture","wrong":["geography","weather","landscape"]}],"spellingErrors":["culchure","cultur","cultue","kulture","cultere","culturre"],"wordFamilyForms":[{"form":"culture","partOfSpeech":"noun","example":"Food is an important part of Italian culture.","pedagogicallyUseful":true},{"form":"cultural","partOfSpeech":"adjective","example":"The city holds a cultural festival every summer.","pedagogicallyUseful":true,"altExample":"Exchange students learn a great deal about cultural differences."},{"form":"culturally","partOfSpeech":"adverb","example":"The class is culturally mixed, with students from twelve countries.","pedagogicallyUseful":true,"altExample":"The festival is culturally important to the whole region."}],"masteryPassages":[{"passageId":"u2_35_culture_passage_1","contextId":"u2_35_culture_gap_1","text":"When you travel abroad, you should learn about the local ____. Customs such as greetings, food and festivals can be very different from your own.","answer":"culture"},{"passageId":"u2_35_culture_passage_2","contextId":"u2_35_culture_gap_2","text":"Language and history are important, but they are only part of a ____. Music, clothing and daily habits also show how a group of people lives.","answer":"culture"}],"contextDependentParaphrases":[],"wrongParaphrases":["rules of law","level of wealth","style of building"],"misleadingDistractors":["the natural scenery of a place","the system of government of a country","the money used in a country"]}]'::jsonb,'["cultural","culturally"]'::jsonb,'["local culture","popular culture","youth culture"]'::jsonb,'live'),
('vocab_genuine','genuine','adjective','real and not false, fake or pretended','[{"senseId":"genuine_1","meaning":"real and not false, fake or pretended","acceptedParaphrases":["real","authentic"],"masteryContexts":[{"contextId":"u2_36_genuine_meaning","text":"She showed genuine concern when I was ill.","meaning":"sincere, not pretended","wrongMeanings":["sudden, not planned","mild, not strong","private, not shared"]},{"contextId":"u2_36_genuine_paraphrase","text":"The ring is made of genuine gold.","meaning":"real, not imitation","wrongMeanings":["bright, not dull","old, not new","heavy, not light"]}],"situationDistractors":["The shop sold a cheap copy of a famous painting as a souvenir.","He pretended to be interested while checking his phone.","The label said the leather was imitation.","The bag was cheap, bright and very popular with students.","He smiled politely at the visitors and shook hands with each one.","The jewellery was displayed in a locked glass case near the door."],"gapDistractors":[{"contextId":"u2_36_genuine_gap_1","answer":"genuine","wrong":["fake","forged","imitation"]},{"contextId":"u2_36_genuine_gap_2","answer":"genuine","wrong":["pretended","false","artificial"]},{"contextId":"u2_36_genuine_gap_3","answer":"genuine","wrong":["fake","counterfeit","forged"]}],"spellingErrors":["genuin","genwine","genuwine","genuiine","gennuine","genune"],"masteryPassages":[{"passageId":"u2_36_genuine_passage_1","contextId":"u2_36_genuine_gap_1","text":"The teacher could tell that the apology was not just polite words. Her ____ regret showed in her voice and in the way she looked at him.","answer":"genuine"},{"passageId":"u2_36_genuine_passage_2","contextId":"u2_36_genuine_gap_2","text":"The shop sold bags at a very low price. Customers soon discovered that the leather was not ____, because it was a cheap imitation.","answer":"genuine"}],"contextDependentParaphrases":[],"wrongParaphrases":["rare","new","popular"],"misleadingDistractors":["very expensive","old and damaged","copied from another source"]}]'::jsonb,'[]'::jsonb,'["genuine interest","genuine concern","genuine leather"]'::jsonb,'live'),
('vocab_amusing','amusing','adjective','funny and entertaining; making you smile or laugh','[{"senseId":"amusing_1","meaning":"funny and entertaining; making you smile or laugh","acceptedParaphrases":["funny","humorous"],"masteryContexts":[{"contextId":"u2_37_amusing_meaning","text":"My grandfather told an amusing story about his school days.","meaning":"funny and entertaining","wrongMeanings":["strange and worrying","long and tiring","sad and moving"]},{"contextId":"u2_37_amusing_paraphrase","text":"I found the film mildly amusing, but not hilarious.","meaning":"making you smile a little","wrongMeanings":["making you feel a little sleepy","making you feel a little sad","making you feel a little afraid"]}],"situationDistractors":["The audience sat in silence during the sad scene.","The teacher explained a difficult maths problem on the board.","The film showed a frightening storm at sea.","The comedian was tired, and the show finished early.","The lesson was long, and several students found it difficult.","The cat chased the toy across the room, and then fell asleep."],"gapDistractors":[{"contextId":"u2_37_amusing_gap_1","answer":"amusing","wrong":["tragic","serious","frightening"]},{"contextId":"u2_37_amusing_gap_2","answer":"amusing","wrong":["tragic","serious","shocking"]},{"contextId":"u2_37_amusing_gap_3","answer":"amusing","wrong":["tragic","boring","frightening"]}],"spellingErrors":["amuseing","amusung","amussing","amuzing","ammusing","amusinng"],"wordFamilyForms":[{"form":"amusing","partOfSpeech":"adjective","example":"He told an amusing story about his first day at work.","pedagogicallyUseful":true},{"form":"amuse","partOfSpeech":"verb","example":"The clown tried to amuse the children while they waited.","pedagogicallyUseful":true},{"form":"amused","partOfSpeech":"adjective","example":"The teacher looked amused when the class began to laugh.","pedagogicallyUseful":true},{"form":"amusement","partOfSpeech":"noun","example":"To her amusement, the cat chased its own tail.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_37_amusing_passage_1","contextId":"u2_37_amusing_gap_1","text":"My uncle tells stories about his school days. They are never cruel, and they are so ____ that the whole family laughs until they cry.","answer":"amusing"},{"passageId":"u2_37_amusing_passage_2","contextId":"u2_37_amusing_gap_2","text":"The film was not a comedy, but it had a few ____ moments. Several times, the audience smiled at a character’s clumsy mistakes.","answer":"amusing"}],"contextDependentParaphrases":[],"wrongParaphrases":["strange","sad","tiring"],"misleadingDistractors":["sad and serious","difficult to understand","very frightening"]}]'::jsonb,'["amuse","amused","amusement"]'::jsonb,'["amusing story","mildly amusing","rather amusing"]'::jsonb,'live'),
('vocab_competitive','competitive','adjective','wanting very much to win or to be more successful than others','[{"senseId":"competitive_1","meaning":"wanting very much to win or to be more successful than others","acceptedParaphrases":["eager to win","driven to beat others"],"masteryContexts":[{"contextId":"u2_38_competitive_meaning","text":"He is a highly competitive swimmer who trains every day.","meaning":"determined to win","wrongMeanings":["willing to teach others","eager to travel abroad","careful to avoid mistakes"]},{"contextId":"u2_38_competitive_paraphrase","text":"It is a competitive industry, with many companies fighting for customers.","meaning":"involving strong rivalry","wrongMeanings":["involving strong cooperation","involving high prices","involving long training"]}],"situationDistractors":["The two friends played cards for fun and did not keep score.","She shared her sandwiches with the other team after the match.","He gave up the race because he did not care about winning.","The two friends played a relaxed game of tennis and chatted between points.","The shop sells the same books as the one across the road.","The class worked together on a poster, and nobody kept the score."],"gapDistractors":[{"contextId":"u2_38_competitive_gap_1","answer":"competitive","wrong":["relaxed","generous","careless"]},{"contextId":"u2_38_competitive_gap_2","answer":"competitive","wrong":["quiet","relaxed","secure"]},{"contextId":"u2_38_competitive_gap_3","answer":"competitive","wrong":["relaxed","casual","generous"]}],"spellingErrors":["competative","compettitive","competive","competitave","comptitive","competitiv"],"wordFamilyForms":[{"form":"competitive","partOfSpeech":"adjective","example":"The mobile phone market is extremely competitive.","pedagogicallyUseful":true},{"form":"compete","partOfSpeech":"verb","example":"Over a hundred schools compete in the national quiz.","pedagogicallyUseful":true},{"form":"competition","partOfSpeech":"noun","example":"There is fierce competition for places at the best universities.","pedagogicallyUseful":true},{"form":"competitor","partOfSpeech":"noun","example":"Our main competitor has just lowered its prices.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_38_competitive_passage_1","contextId":"u2_38_competitive_gap_1","text":"Mia hates losing at anything, even a quick game of cards. Her friends say she is far too ____, because every game becomes a battle.","answer":"competitive"},{"passageId":"u2_38_competitive_passage_2","contextId":"u2_38_competitive_gap_2","text":"Dozens of companies sell mobile phones in this country. The market is so ____ that firms keep lowering their prices to attract customers.","answer":"competitive"}],"contextDependentParaphrases":[],"wrongParaphrases":["happy to share","afraid to try","ready to quit"],"misleadingDistractors":["friendly and relaxed","unwilling to take part","not very good at sport"]}]'::jsonb,'["compete","competition","competitor"]'::jsonb,'["competitive market","highly competitive","competitive sport"]'::jsonb,'live'),
('vocab_critical','critical','adjective','expressing disapproval of someone or something, or pointing out their faults','[{"senseId":"critical_1","meaning":"expressing disapproval of someone or something, or pointing out their faults","acceptedParaphrases":["disapproving","fault-finding"],"masteryContexts":[{"contextId":"u2_39_critical_meaning","text":"Parents were critical of the new homework policy.","meaning":"expressing disapproval of","wrongMeanings":["showing great respect for","paying close attention to","giving full support to"]},{"contextId":"u2_39_critical_paraphrase","text":"She is too critical of her own work.","meaning":"quick to find faults","wrongMeanings":["quick to forgive mistakes","quick to ask for help","quick to praise others"]}],"situationDistractors":["The judges praised every performance and gave full marks.","The teacher congratulated the class on its excellent results.","Reviewers called the film brilliant and moving.","The report was long and contained many tables of figures.","The teacher praised the whole class for the way they worked.","The manager explained the new rules clearly and then asked for questions."],"gapDistractors":[{"contextId":"u2_39_critical_gap_1","answer":"critical","wrong":["supportive","proud","approving"]},{"contextId":"u2_39_critical_gap_2","answer":"critical","wrong":["supportive","encouraging","kind"]},{"contextId":"u2_39_critical_gap_3","answer":"critical","wrong":["cheerful","grateful","easy-going"]}],"spellingErrors":["critcal","critacal","critticall","criticle","critial","cricital"],"wordFamilyForms":[{"form":"critical","partOfSpeech":"adjective","example":"The report was highly critical of the way the school was run.","pedagogicallyUseful":true},{"form":"criticise","partOfSpeech":"verb","example":"It is easy to criticise other people’s work.","pedagogicallyUseful":true},{"form":"criticism","partOfSpeech":"noun","example":"The headteacher accepted the criticism and promised to change the policy.","pedagogicallyUseful":true},{"form":"critic","partOfSpeech":"noun","example":"The film critic gave the new comedy an excellent review.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_39_critical_passage_1","contextId":"u2_39_critical_gap_1","text":"Some parents liked the new timetable, but many were ____ of it. They complained that the lessons started too early and finished too late.","answer":"critical"},{"passageId":"u2_39_critical_passage_2","contextId":"u2_39_critical_gap_2","text":"Good friends can be honest, but nobody enjoys being told that everything they do is wrong. Her father was always ____ of her work and rarely praised it.","answer":"critical"}],"contextDependentParaphrases":[],"wrongParaphrases":["approving","indifferent","grateful"],"misleadingDistractors":["full of praise","too tired to notice","unable to decide"]}]'::jsonb,'["criticise","criticism","critic"]'::jsonb,'["critical review","extremely critical","critical comment"]'::jsonb,'live'),
('vocab_impressive','impressive','adjective','causing admiration because of great skill, size or quality','[{"senseId":"impressive_1","meaning":"causing admiration because of great skill, size or quality","acceptedParaphrases":["remarkable","admirable"],"masteryContexts":[{"contextId":"u2_40_impressive_meaning","text":"The view from the tower is truly impressive.","meaning":"causing admiration","wrongMeanings":["causing confusion","causing delay","causing worry"]},{"contextId":"u2_40_impressive_paraphrase","text":"He gave an impressive speech without using any notes.","meaning":"showing great skill","wrongMeanings":["showing great nervousness","showing great luck","showing great length"]}],"situationDistractors":["The team lost every match and finished at the bottom of the league.","The presentation was short and covered only basic facts.","The painting looked similar to many others in the shop.","The exam was long, and the questions were difficult.","The student arrived early, took out a pen and began to write.","The film lasted two hours and finished late in the evening."],"gapDistractors":[{"contextId":"u2_40_impressive_gap_1","answer":"impressive","wrong":["disappointing","ordinary","boring"]},{"contextId":"u2_40_impressive_gap_2","answer":"impressive","wrong":["ordinary","boring","disappointing"]},{"contextId":"u2_40_impressive_gap_3","answer":"impressive","wrong":["average","weak","disappointing"]}],"spellingErrors":["impresive","impressiv","impressave","imprressive","impresssive","inpressive"],"wordFamilyForms":[{"form":"impressive","partOfSpeech":"adjective","example":"The view from the top of the tower is truly impressive.","pedagogicallyUseful":true},{"form":"impress","partOfSpeech":"verb","example":"She worked hard to impress the interview panel.","pedagogicallyUseful":true},{"form":"impressed","partOfSpeech":"adjective","example":"The examiner was impressed by her fluent answers.","pedagogicallyUseful":true},{"form":"impressively","partOfSpeech":"adverb","example":"The young goalkeeper played impressively in her first match.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_40_impressive_passage_1","contextId":"u2_40_impressive_gap_1","text":"The young pianist played for two hours without a single mistake. The audience stood up and clapped, because the performance was truly ____.","answer":"impressive"},{"passageId":"u2_40_impressive_passage_2","contextId":"u2_40_impressive_gap_2","text":"The new stadium holds eighty thousand people and has a roof that opens in minutes. Visitors often say it is the most ____ building in the city.","answer":"impressive"}],"contextDependentParaphrases":[],"wrongParaphrases":["ordinary","disappointing","confusing"],"misleadingDistractors":["disappointing and weak","ordinary and average","slightly unusual"]}]'::jsonb,'["impress","impressed","impressively"]'::jsonb,'["impressive performance","truly impressive","impressive results"]'::jsonb,'live')
